CREATE COLUMN TABLE "TEST_AP"."ORTT" ("RateDate" LONGDATE CS_LONGDATE NOT NULL , "Currency" NVARCHAR(3) NOT NULL , "Rate" DECIMAL(21,6) CS_FIXED, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("RateDate", "Currency")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ORTT_DATE" ON "TEST_AP"."ORTT" ( "RateDate" ASC )